probe_script:
const root = '/home/cassandra/tradecloseout';
const { randomUUID, createHash } = require('node:crypto');
const fs = require('node:fs');
const pick = (m, key) => m[key] || m.default[key];
const findings = [];
async function probe(name, fn) {
  try { findings.push({ name, result: await fn() }); }
  catch (e) { findings.push({ name, error: { code: e.code, message: e.message, response: e.response } }); }
}
(async () => {
  const helper = await import(`${root}/packages/db/test/helpers/disposable-database.ts`);
  const fixtures = await import(`${root}/packages/db/test/helpers/fixtures.ts`);
  const am = await import(`${root}/apps/api/src/modules/assets/assets.service.ts`);
  const hm = await import(`${root}/apps/api/src/modules/handover/handover.service.ts`);
  const cm = await import(`${root}/apps/api/src/modules/commissioning/commissioning.service.ts`);
  const wm = await import(`${root}/apps/api/src/modules/billing/warranty-and-billing.service.ts`);
  await pick(helper, 'withDisposableDatabase')(async ({ admin, app }) => {
    const { userId, tenants: [a] } = await pick(fixtures, 'seedTenants')(admin);
    const org = a.orgId, project = a.projectIds[0];
    const verifier = randomUUID();
    await admin.query(`INSERT INTO users (id,name,status) VALUES ($1,'Probe verifier','ACTIVE')`, [verifier]);
    const ctx = { orgId: org, userId, actorType: 'MEMBER', orgRole: 'R-OWNER', ip: '127.0.0.1', userAgent: 'gap-probe', requestId: randomUUID() };
    const vctx = { ...ctx, userId: verifier, orgRole: 'R-PM' };
    const assets = new (pick(am, 'AssetsService'))(app);
    let signed;
    const handover = new (pick(hm, 'HandoverService'))(app, { createSignedDownloadUrl: async opts => { signed = opts; return 'https://probe.invalid/download'; } });
    const commission = new (pick(cm, 'CommissioningService'))(app);
    const warranty = new (pick(wm, 'WarrantyAndBillingService'))(app);
    const assetA = randomUUID(), assetB = randomUUID();
    for (const [id, tag] of [[assetA, 'A'], [assetB, 'B']]) {
      await admin.query(`INSERT INTO assets (id,org_id,project_id,tag,name,category_key,created_by) VALUES ($1,$2,$3,$4,$4,'HVAC_AHU',$5)`, [id,org,project,tag,userId]);
    }
    await probe('equipment_passport_real_database', () => assets.getEquipmentPassport(ctx, project, assetA));

    const object = randomUUID(), doc = randomUUID(), version = randomUUID(), revision = randomUUID(), reval = randomUUID();
    const sha = 'a'.repeat(64);
    await admin.query(`INSERT INTO storage_objects (id,org_id,bucket,object_key,mime,size_bytes,observed_size_bytes,sha256,status,provider_version_id) VALUES ($1,$2,'vault',$3,'application/pdf',1024,1024,$4,'READY','v1')`, [object,org,`uploads/${object}`,sha]);
    await admin.query(`INSERT INTO documents (id,org_id,project_id,title,doc_type_key,category_key,status,created_by) VALUES ($1,$2,$3,'Generic manual','MANUAL','EQUIPMENT','ACTIVE',$4)`, [doc,org,project,userId]);
    await admin.query(`INSERT INTO document_versions (id,org_id,project_id,document_id,version_no,revision_code,object_id,file_status,review_status,issue_date,uploaded_by) VALUES ($1,$2,$3,$4,1,'R0',$5,'READY','APPROVED',CURRENT_DATE,$6)`, [version,org,project,doc,object,userId]);
    await admin.query(`UPDATE documents SET current_approved_version_id=$1 WHERE id=$2`, [version,doc]);
    await admin.query(`INSERT INTO asset_identity_revisions (id,org_id,project_id,asset_id,revision_no,tag,name,reason,created_by) VALUES ($1,$2,$3,$4,1,'A','A','Probe change',$5)`, [revision,org,project,assetA,userId]);
    await admin.query(`INSERT INTO evidence_revalidations (id,org_id,project_id,asset_id,identity_revision_id,document_version_id,status) VALUES ($1,$2,$3,$4,$5,$6,'PENDING')`, [reval,org,project,assetA,revision,version]);
    await probe('revalidation_without_expected_version', async () => {
      const r = await assets.revalidateEvidence(vctx, project, assetA, reval, { status: 'CONFIRMED' });
      return { status: r.status, rowVersion: r.row_version };
    });
    await admin.query(`UPDATE evidence_revalidations SET status='PENDING' WHERE id=$1`, [reval]);
    const snapshot = randomUUID(), requirement = randomUUID();
    await admin.query(`INSERT INTO checklist_snapshots (id,org_id,project_id,version_no,status,resolved_payload_json,provenance_json,source_json,checksum,created_by) VALUES ($1,$2,$3,1,'ACTIVE','{}','{}','{}',$4,$5)`, [snapshot,org,project,sha,userId]);
    await admin.query(`INSERT INTO requirements (id,org_id,project_id,current_snapshot_id,requirement_key,scope_key,asset_id,group_key,title,doc_type_key,mandatory,status) VALUES ($1,$2,$3,$4,'MANUAL-B',$5,$6,'HVAC','Manual for B','MANUAL',true,'APPROVED')`, [requirement,org,project,snapshot,`asset:${assetB}`,assetB]);
    await admin.query(`INSERT INTO document_requirements (id,org_id,project_id,document_id,requirement_id) VALUES ($1,$2,$3,$4,$5)`, [randomUUID(),org,project,doc,requirement]);
    await probe('shared_manual_B_readiness_while_A_pending', async () => {
      const r = await handover.evaluateProjectReadiness(ctx, project);
      return { ready: r.readyWithoutOverride, missing: r.blockers.missingMandatoryCount };
    });
    await probe('shared_manual_B_package_generation_while_A_pending', () => handover.requestHandoverPackageGeneration(ctx, project, { title: 'Scope probe' }));

    await probe('TAB_rounding_boundary_without_source_procedure', async () => {
      const r = await commission.recordTabWorksheet(ctx, project, { systemType: 'AIR_SIDE', worksheetType: 'PROBE', readings: [{ terminalOrTag: 'A', designFlow: 100, actualFlow: 89.996, unit: 'CFM' }] });
      return { status: r.status, rawDeviationPercent: Math.abs(89.996-100), storedDeviationPercent: r.readings[0].deviationPercent, tolerancePercent: r.designSummary.tolerancePercent };
    });

    const archiveObject = randomUUID(), archive = randomUUID(), archiveKey = `archives/${archive}/export.zip`;
    await admin.query(`INSERT INTO storage_objects (id,org_id,bucket,object_key,mime,size_bytes,sha256,status) VALUES ($1,$2,'vault',$3,'application/zip',2048,$4,'READY')`, [archiveObject,org,archiveKey,sha]);
    await admin.query(`INSERT INTO archive_exports (id,org_id,project_id,status,archive_sha256,verification_receipt_json) VALUES ($1,$2,$3,'COMPLETED',$4,$5)`, [archive,org,project,sha,JSON.stringify({artifact:{objectId:archiveObject,objectKey:archiveKey,bucket:'vault',providerVersionId:'claimed-pinned-version',sizeBytes:2048,sha256:sha}})]);
    await probe('archive_READY_row_without_observed_size_or_provider_version', async () => {
      signed = undefined;
      const r = await handover.getArchiveExport(ctx, project, archive);
      return { accepted: !!r.downloadUrl, signedVersionId: signed?.versionId, signedBucket: signed?.bucket };
    });

    const pkg = randomUUID(), submission = randomUUID(), party1 = randomUUID(), party2 = randomUUID(), rec1 = randomUUID(), rec2 = randomUUID(), grant = randomUUID();
    await admin.query(`INSERT INTO handover_packages (id,org_id,project_id,title,status,snapshot_checksum,created_by) VALUES ($1,$2,$3,'Probe','READY',$4,$5)`, [pkg,org,project,sha,userId]);
    await admin.query(`INSERT INTO submissions (id,org_id,project_id,package_id,method,status,created_by) VALUES ($1,$2,$3,$4,'PORTAL','SUBMITTED',$5)`, [submission,org,project,pkg,userId]);
    for (const [id,name] of [[party1,'Required client'],[party2,'Optional observer']]) await admin.query(`INSERT INTO parties (id,org_id,name,types,status) VALUES ($1,$2,$3,ARRAY['CLIENT'],'ACTIVE')`, [id,org,name]);
    for (const [id,party,required] of [[rec1,party1,true],[rec2,party2,false]]) await admin.query(`INSERT INTO submission_recipients (id,org_id,project_id,submission_id,recipient_party_id,role,status,is_required_approver) VALUES ($1,$2,$3,$4,$5,'CLIENT_REP','SENT',$6)`, [id,org,project,submission,party,required]);
    await admin.query(`INSERT INTO guest_grants (id,org_id,project_id,party_id,target_email,grant_type,role,capabilities,scope_json,token_hash,expires_at,created_by) VALUES ($1,$2,$3,$4,'probe@example.invalid','CLIENT_VIEW','R-CLIENT',ARRAY['package.accept'],$5,$6,now()+interval '1 day',$7)`, [grant,org,project,party1,JSON.stringify({submissionIds:[randomUUID()]}),createHash('sha256').update(grant).digest('hex'),userId]);
    await probe('decision_with_guest_grant_scoped_to_another_submission', async () => {
      const r = await handover.recordRecipientSubmissionDecision({...ctx,actorType:'GUEST',guestGrantId:grant,guestCapabilities:['package.accept']},project,submission,{recipientPartyId:party1,decision:'ACCEPT'});
      return { acceptedDecision: true, aggregateStatus: r.status, optionalRecipientPending: true };
    });
    await probe('optional_recipient_rejection_changes_aggregate', async () => {
      const r = await handover.recordRecipientSubmissionDecision(ctx,project,submission,{recipientPartyId:party2,decision:'REJECT',remarks:'Observer comment only'});
      return { aggregateStatus: r.status };
    });

    const defect = randomUUID();
    await admin.query(`INSERT INTO defects (id,org_id,project_id,asset_id,title,description,severity,status,raised_by) VALUES ($1,$2,$3,$4,'Probe defect','Probe defect','CRITICAL','OPEN',$5)`, [defect,org,project,assetA,userId]);
    await probe('defect_remedy_with_generic_manual_without_asset_link', () => warranty.submitDefectRemedy(ctx,project,defect,object,1));
    const otherObject = randomUUID(), otherVersion = randomUUID();
    await admin.query(`INSERT INTO storage_objects (id,org_id,bucket,object_key,mime,size_bytes,observed_size_bytes,sha256,status,provider_version_id) VALUES ($1,$2,'vault',$3,'application/pdf',1024,1024,$4,'READY','v2')`, [otherObject,org,`uploads/${otherObject}`,sha]);
    await admin.query(`INSERT INTO document_versions (id,org_id,project_id,document_id,version_no,revision_code,object_id,file_status,review_status,issue_date,uploaded_by) VALUES ($1,$2,$3,$4,2,'R1',$5,'READY','NOT_SUBMITTED',CURRENT_DATE,$6)`, [otherVersion,org,project,doc,otherObject,userId]);
    await probe('defect_close_with_different_unreviewed_manual_version', () => warranty.closeDefect(vctx,project,defect,otherObject,2));
  });
  fs.writeFileSync('/tmp/tradecloseout-real-gap-recheck-results.json', JSON.stringify(findings,null,2)+'\n');
  for (const finding of findings) console.log(JSON.stringify(finding));
})().catch(e => { console.error(e.code || '',e.message); process.exitCode = 1; });
